import{_ as t,c as o,o as a,a4 as e}from"./chunks/framework.BYxathSa.js";const g=JSON.parse('{"title":"Q7：React Hooks 基本原理及规则","description":"","frontmatter":{},"headers":[],"relativePath":"react/q7.md","filePath":"react/q7.md","lastUpdated":null}'),s={name:"react/q7.md"},r=e('<h1 id="q7-react-hooks-基本原理及规则" tabindex="-1">Q7：React Hooks 基本原理及规则 <a class="header-anchor" href="#q7-react-hooks-基本原理及规则" aria-label="Permalink to &quot;Q7：React Hooks 基本原理及规则&quot;">​</a></h1><p><strong>原理</strong>：React 通过链表（或数组）按 Hooks 的调用顺序来存储每一个 Hook 的状态。函数组件的每次渲染都会按照同样的顺序获取对应的状态，从而能让函数“记住”上一次的值。</p><p><strong>规则</strong>：</p><ol><li>只在函数组件的<strong>最顶层</strong>调用 Hooks，<strong>不要在循环、条件或嵌套函数</strong>中使用。因为 React 依赖调用顺序来正确关联状态。</li><li>只在 <strong>React 函数组件或自定义 Hook</strong> 中调用 Hooks，不要在普通 JavaScript 函数中使用。</li></ol>',4),c=[r];function n(_,i,l,d,p,h){return a(),o("div",null,c)}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
